package com.arjunren.banking.controller;
import com.arjunren.banking.dto.Dtos.*; import com.arjunren.banking.entity.AppUser; import com.arjunren.banking.exception.DomainException; import com.arjunren.banking.service.*; import jakarta.servlet.http.HttpServletRequest; import jakarta.validation.Valid; import java.util.Map; import org.springframework.http.*; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/auth") public class AuthController{private final AuthService auth;private final LoginRateLimiter limiter;public AuthController(AuthService auth,LoginRateLimiter limiter){this.auth=auth;this.limiter=limiter;}@PostMapping("/register")@ResponseStatus(HttpStatus.CREATED)Map<String,Object> register(@Valid @RequestBody RegisterRequest r){return Map.of("data",auth.register(r));}@PostMapping("/login")Map<String,Object> login(@Valid @RequestBody LoginRequest r,HttpServletRequest request){limiter.check(request.getRemoteAddr());return Map.of("data",auth.login(r));}@PostMapping("/logout")@ResponseStatus(HttpStatus.NO_CONTENT)void logout(@AuthenticationPrincipal AppUser user,HttpServletRequest request){String h=request.getHeader("Authorization");if(h==null||!h.startsWith("Bearer "))throw new DomainException(HttpStatus.UNAUTHORIZED,"Bearer token required");auth.logout(h.substring(7));}}

